const $=s=>localizedElement(document.querySelector(s)),escapeText=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),esc=v=>protect(escapeText(v)),yen=n=>'¥'+n.toLocaleString('ja-JP');
