const recordColor=r=>recordColors.some(([c])=>c===r.icon_color)?r.icon_color:defaultIconColor;
const recordKey=r=>r.icon==='box'?'hotel':r.icon||'';
const recordBadge=r=>recordKey(r)&&recordOptions.some(([k])=>k===recordKey(r))?`<span class="record-icon" style="color:${recordColor(r)}">${recordSvg(recordKey(r))}</span>`:'';
function recordPicker(r={}){return `<div class="record-picker" style="--record-color:${recordColor(r)}"><div class="record-options" role="group" aria-label="アイコンを選択">${recordOptions.map(([key,name])=>`<label class="record-choice"><input type="radio" name="icon" value="${key}" aria-label="${escapeText(tr(name))}" ${recordKey(r)===key?'checked':''}><span>${recordSvg(key)}</span></label>`).join('')}</div><div class="record-colors" role="group" aria-label="${escapeText(tr('色を選択'))}">${recordColors.map(([color,name])=>`<label class="record-color" style="--swatch:${color}"><input type="radio" name="icon_color" value="${color}" aria-label="${escapeText(tr(name))}" ${recordColor(r)===color?'checked':''}><span></span></label>`).join('')}</div></div>`}
const recordValues=f=>({icon:f.get('icon')||'',icon_color:f.get('icon_color')||defaultIconColor});
document.addEventListener('change',e=>{if(e.target.name==='icon_color')e.target.closest('.record-picker')?.style.setProperty('--record-color',e.target.value)});
// プレビューは実日付ではなく、いつ見ても同じ残り日数を見せる。
let demoMode=false;const demoDays=3;
// scrollIntoViewはiframeの中で呼ぶと親ページごと動かしてしまう。中の入れ物だけをずらす。
function scrollWithin(el,align='nearest'){
 if(!el)return;let box=el.parentElement;
 while(box&&box!==document.body&&!(/(auto|scroll)/.test(getComputedStyle(box).overflowY)&&box.scrollHeight>box.clientHeight+1))box=box.parentElement;
 if(!box||box===document.body)return;
 const e=el.getBoundingClientRect(),b=box.getBoundingClientRect();
 if(align==='center')box.scrollTop+=e.top-b.top-(b.height-e.height)/2;
 else if(e.top<b.top)box.scrollTop+=e.top-b.top;
 else if(e.bottom>b.bottom)box.scrollTop+=e.bottom-b.bottom;
}
let migrationBackupAvailable=false;
let lastTab='',state,tab='home',bagIndex=0,taskView='list',cart={},paid=0,busy=false,offline=false,setupStep=0,draft={},editingEvent=null,channel;
const event=()=>state.events.find(e=>e.id===state.active);
const eventText=(m,text)=>m.translations?.[language()]?.[text]??((m.key==='kemoket-17-2026'||m.distribution?.key==='kemoket-17-2026')?tr(text):text);
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function mutate(fn,renderAfter=true){const r=await changeState(fn);state=r.state;channel?.postMessage('changed');if(renderAfter)render();return r.result}
function changeEvent(fn,renderAfter=true,id=state.active){return mutate(s=>{const e=s.events.find(e=>e.id===id);if(!e)throw Error('イベントが見つかりません。');return fn(e)},renderAfter)}
function modal(title,body,submit){const d=$('#modal');d.innerHTML=`<form><div class="row spread"><h2>${escapeText(tr(title))}</h2>${btn('close','×','quiet','aria-label="閉じる"')}</div>${body}${submit?'<div class="buttons"><button class="primary" type="submit">保存</button></div>':''}<p class="error" role="alert"></p></form>`;if(!d.open)d.showModal();initTimeWheels(d);d.querySelector('form').onsubmit=async ev=>{ev.preventDefault();if(busy)return;busy=true;try{await submit(new FormData(ev.target));d.close()}catch(e){d.querySelector('.error').textContent=tr(e.message)}finally{busy=false}}}
const field=(label,name,value='',type='text',extra='')=>type==='time'?timeField(label,name,value):`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>${type==='file'&&window.CirclePrepAndroid?'<small class="muted">選択をやめるときはAndroidの戻るボタン／画面端からの戻る操作を使います。</small>':''}</label>`;
const check=(label,name,on)=>`<label class="row"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;
function clock(){const now=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now),p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}:${p.second}`,now}}
function tick(){const c=clock();if($('#clock'))$('#clock').innerHTML=`${c.date.replaceAll('-','.')} <span class="small">${new Intl.DateTimeFormat('en',{weekday:'short',timeZone:'Asia/Tokyo'}).format(c.now).toUpperCase()}</span><span class="time">${c.time}</span>`;if($('#countdown')){const m=event().metadata;let text='開催日未定';if(demoMode){text=tr('イベントまで {count} 日').replace('{count}',demoDays)}else if(m.date){const delta=new Date(m.date+'T'+(m.entry_time||'00:00')+':00+09:00')-c.now;const days=Math.ceil((new Date(m.date+'T00:00:00+09:00')-new Date(c.date+'T00:00:00+09:00'))/86400000);text=days<0?'お疲れさまでした！':days===0?'イベント当日！':tr('イベントまで {count} 日').replace('{count}',days);if(m.entry_time&&delta>0&&delta<259200000){const sec=Math.floor(delta/1000);text=`サークル入場まで<strong class="digit">${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}</strong>`}}$('#countdown').innerHTML=text;const active=m.date===c.date?(m.schedule||[]).filter(s=>s.start<=c.time.slice(0,5)&&(!s.end||s.end>c.time.slice(0,5))):[];$('#notice').textContent=active.map(s=>eventText(m,s.title)).join(' · ')}}
// 頒布物を押した合図の粒。記録には関係しない見た目だけの演出。
const burstTints=['#c85153','#e0a24a','#71937a','#d88aa0','#7f94c4'];
function burst(el,ev){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const box=el.getBoundingClientRect();
 const x=ev&&ev.clientX?ev.clientX:box.left+box.width/2;
 const y=ev&&ev.clientY?ev.clientY:box.top+box.height/2;
 const layer=document.createElement('div');
 layer.className='burst';layer.style.transform=`translate(${x}px,${y}px)`;
 for(let i=0;i<14;i++){
  const angle=(Math.PI*2*i)/14+Math.random()*.4,distance=34+Math.random()*46,dot=document.createElement('i');
  dot.style.setProperty('--dx',`${Math.cos(angle)*distance}px`);
  dot.style.setProperty('--dy',`${Math.sin(angle)*distance-14}px`);
  dot.style.setProperty('--size',`${6+Math.random()*7}px`);
  dot.style.setProperty('--tint',burstTints[i%burstTints.length]);
  dot.style.animationDelay=`${Math.random()*70}ms`;
  layer.append(dot);
 }
 document.body.append(layer);
 setTimeout(()=>layer.remove(),900);
}
function taskRow(t){const overdue=!t.done&&t.date&&new Date(`${t.date}T${t.time||'23:59'}:00+09:00`).getTime()<Date.now();return `<div class="listrow ${overdue?'overdue':''}" data-task="${esc(t.id)}"><input type="checkbox" aria-label="${esc(t.name)} ${tr("完了")}" data-action="task-check" data-id="${esc(t.id)}" ${t.done?'checked':''}>${recordBadge(t)}<div class="text ${t.done?'done':''}">${esc(t.name)}<div class="muted digit">${esc([t.date,t.time].filter(Boolean).join(' '))}</div></div>${ib('task-edit','edit','やることを編集',`data-id="${esc(t.id)}"`)}${ib('task-delete','trash','やることを削除',`data-id="${esc(t.id)}"`)}</div>`}
function guide(){const m=event().metadata,official=m.key==='kemoket-17-2026'||m.distribution?.key==='kemoket-17-2026';const guideText=x=>eventText(m,x);return `<div id="guide-items">${(event().metadata.guide||[]).map(s=>`<section class="guide-card"><h2>${esc(guideText(s.title))}</h2>${s.items.map(x=>`<p ${/禁止|不可|厳禁/.test(x)?'class="danger" style="font-weight:750"':''}>${esc(guideText(x))}</p>`).join('')}</section>`).join('')||'<p class="muted">同梱データを取得すると、注意事項が表示されます。</p>'}</div><label class="guide-search row">${icon('search')}<input type="search" id="guide-query" placeholder="注意事項を検索" aria-label="注意事項を検索"></label>`}
function home(){const e=event(),items=e.bags.flatMap(b=>b.items.map(i=>({...i,bag:b.id}))),morning=items.filter(i=>i.morning);return `<div id="countdown" class="countdown"></div><div id="notice" class="notice" aria-live="polite"></div>${nextEventCard()}<div class="summary-grid">${[['当日朝のチェック',morning.map(i=>`<label class="row"><input type="checkbox" data-action="item-check" data-bag="${i.bag}" data-id="${i.id}" ${i.done?'checked':''}>${recordBadge(i)}${esc(i.name)}</label>`).join('')||'<p class="muted">持ち物の編集で「当日朝」にチェックできます。</p>'],['荷造り',e.bags.map((b,i)=>btn('bag-open',`${esc(b.name)}　${b.items.filter(x=>x.done).length}/${b.items.length}`,'card',`data-index="${i}"`)).join('')||'<p class="muted">荷物タブから追加できます。</p>'],['次にやること',e.tasks.filter(t=>!t.done).slice(0,5).map(taskRow).join('')||'<p>いまのところ完了です！</p>'],['注意事項',guide()]].map(([name,body])=>`<details class="card"><summary>${name}</summary><div class="detail">${body}</div></details>`).join('')}</div>`}
function bags(){const b=event().bags[bagIndex];return `<div class="bagtabs">${Array.from({length:5},(_,i)=>{const name=event().bags[i]?.name||tr('荷物{p0}').replace('{p0}',i+1);return btn('bag-select',esc(name.slice(0,8)+(name.length>8?'…':'')),i===bagIndex?'selected':'',`data-index="${i}" title="${esc(name)}"`)}).join('')}</div><div class="card bag-card">${b?`<h2 class="row">${esc(b.name)}${ib('bag-edit','edit','バッグを編集')}</h2>${b.shipping?`<p class="muted">${tr("宅配便")} → ${esc(b.destination||tr('送り先未定'))}</p>${b.tracking?`<a href="https://toi.kuronekoyamato.co.jp/cgi-bin/tneko?number01=${encodeURIComponent(b.tracking)}" target="_blank" rel="noopener">${esc(b.tracking)} ↗</a>`:''}`:''}<div class="bag-items" data-bag-id="${b.id}">${b.items.map(i=>`<div class="listrow" data-bag-item="${i.id}"><input type="checkbox" data-action="item-check" data-bag="${b.id}" data-id="${i.id}" aria-label="${esc(i.name)} ${tr("用意済み")}" ${i.done?'checked':''}>${recordBadge(i)}<span class="text ${i.done?'done':''}">${esc(i.name)}${i.morning?' ☀':''}</span>${ib('item-edit','edit','持ち物を編集',`data-id="${i.id}"`)}</div>`).join('')}</div><div class="add-footer">${ib('items-add','plus','持ち物を追加')}</div>`:`<div class="empty">${btn('bag-add',icon('plus')+'<br>バッグを追加','primary')}</div>`}</div>`}
function tasks(){let list=event().tasks.slice().sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'').localeCompare(b.time||''));let content=list.length?`<div class="task-list">${list.map(taskRow).join('')}</div>`:'';if(taskView==='timeline'){const c=clock(),nowKey=c.date+' '+c.time;let added=false,last='';content=list.map(t=>{let pre='';const key=(t.date||'9999')+' '+(t.time||'23:59');if(!added&&key>=nowKey){pre+='<div class="now" id="now">NOW</div>';added=true}if(last!==t.date){last=t.date;pre+=`<div class="date-marker">${esc(t.date||'UNSCHEDULED')}</div>`}return pre+taskRow(t)}).join('');if(!added)content+='<div class="now" id="now">NOW</div>';content=`<div class="timeline">${content}</div>`}return `<div class="chips">${btn('task-view','やることリスト',taskView==='list'?'selected':'','data-view="list"')}${btn('task-view','タイムライン',taskView==='timeline'?'selected':'','data-view="timeline"')}</div>${content||'<div class="empty">やることを追加しましょう</div>'}<div class="add-footer">${ib('task-add','plus','やることを追加')}</div>`}
function total(){return event().register.products.reduce((n,p)=>n+p.price*(cart[p.id]||0),0)}
// レジの支払いモード。高速＝お預かりを入れず、頒布物を押して確定。電卓＝テンキーで入力。ボタン式＝100〜10,000円のボタンを足していく。
const regModes=[['fast','高速'],['calc','電卓'],['bills','ボタン式']];
const regMode=()=>regModes.some(([m])=>m===state.preferences.regMode)?state.preferences.regMode:'fast';
function checkoutHTML(){
 const t=total(),diff=paid-t,mode=regMode(),lines=event().register.products.filter(p=>cart[p.id]>0),has=lines.length>0,count=lines.reduce((n,p)=>n+cart[p.id],0);
 const switcher=`<div class="mode-switch" role="group" aria-label="レジのモード">${regModes.map(([m,l])=>btn('reg-mode',l,mode===m?'primary':'',`data-mode="${m}" aria-pressed="${mode===m}"`)).join('')}</div>`;
 const pad=`<div class="keypad">${['7','8','9','4','5','6','1','2','3','0','00','back'].map(k=>k==='back'?btn('key',icon('back'),'key-back',`data-key="back" aria-label="1文字消す"`):btn('key',k,'digit',`data-key="${k}"`)).join('')}${btn('key','ちょうど','key-exact','data-key="exact"')}${btn('key','C','key-clear digit','data-key="C" aria-label="お預かりを消去"')}</div>`;
 const bills=`<div class="keypad bills">${[100,500,1000,5000,10000].map(v=>btn('key','+'+v.toLocaleString('en-US'),'digit',`data-key="+${v}"`)).join('')}${btn('key','C','key-clear digit','data-key="C" aria-label="お預かりを消去"')}${btn('key','ちょうど','key-exact','data-key="exact"')}</div>`;
 const info=mode==='fast'
  ?`${switcher}<div class="fast-total"><span>会計</span><b class="digit">${yen(t)}</b><small>${has?tr('{count}点').replace('{count}',count):'頒布物を押してください'}</small></div><ul class="fast-lines">${lines.map(p=>`<li><span>${esc(p.name)}</span><b class="digit">×${cart[p.id]}</b></li>`).join('')}</ul>`
  :`${switcher}<div class="amount-row">お預かり<b class="digit paid">${yen(paid)}</b></div><div class="amount-row">会計<b>${yen(t)}</b></div><div class="amount-row">お釣り<b class="change ${diff<0?'negative':''}">${paid>=100000?'Error!':(diff<0?'−':'')+yen(Math.abs(diff))}</b></div>${mode==='bills'?bills:pad}`;
 const blocked=mode==='fast'?!has:(!has||paid<t||paid>=100000);
 return `<div class="checkout" data-mode="${mode}"><div class="checkout-main">${info}</div><div class="actions">${btn('checkout',tr('会計\n確定').replace('\n','<br>'),'red confirm',blocked?'disabled':'')}${btn('gift','取り置き','green gift',!has?'disabled':'')}</div></div>`;
}
