function register(){const e=event();return `<div class="products" data-grid="${e.grid||'medium'}">${e.register.products.filter(p=>p.active).map(p=>`<div class="product ${p.stock===0?'soldout':''}" role="button" tabindex="0" aria-label="${esc(p.name)} ${yen(p.price)} ${tr("追加")}" data-action="product-tap" data-id="${p.id}">${p.image?`<canvas class="product-image" width="480" height="480" data-product-image="${p.id}"></canvas>`:`<div class="placeholder">${esc(p.name)}</div>`}<div class="stock">${p.stock}</div>${p.release_mark?`<span class="mark">${C.markLabel(p.release_mark)}</span>`:''}${cart[p.id]?`<span class="quantity" data-q="${cart[p.id]}">${cart[p.id]}</span>${ib('product-reset','reset','選択数量をリセット',`data-id="${p.id}"`).replace('iconbtn','reset')}`:''}<div class="caption"><b class="price">${yen(p.price)}</b><span class="name">${esc(p.name)}</span></div>${p.stock===0?'<div class="soldout-label">SOLD<br>OUT</div>':''}</div>`).join('')||'<div class="empty">「設定詳細」の「頒布物編集」から頒布物を登録</div>'}</div>${checkoutHTML()}`}
