function render(){const previousNav=document.querySelector('.bottom');const navLanguage=language();const scroll=lastTab===tab?($('.products')?.scrollTop||0):0;lastTab=tab;if(!state.events.length){setup();return}document.documentElement.style.fontSize=state.preferences.size+'px';$('#app').innerHTML=`<div class="shell"><header class="top"><div class="event-name">${esc(eventText(event().metadata,event().metadata.name))}</div>${tab==='register'?btn('reg-detail',icon('gear')+'<span>設定詳細</span>','detail-btn','aria-haspopup="dialog"'):tab==='tasks'?btn('task-add',icon('plus'),'iconbtn hdr-add','aria-label="やることを追加"'):tab==='bags'&&event().bags[bagIndex]?btn('items-add',icon('plus'),'iconbtn hdr-add','aria-label="持ち物を追加"'):''}<div class="clock digit" id="clock"></div></header><main data-motion-screen="${tab}" class="content ${tab==='register'?'register-content':tab==='map'?'map-content':tab==='notes'?'notes-content':''}">${(tab==='map'?mapScreen(event()):tab==='notes'?notesScreen(event()):({home,bags,tasks,register,settings}[tab])())}</main><nav class="bottom" aria-label="メインメニュー">${[['bags','荷物'],['tasks','やるべきこと'],['notes','メモ'],['home','ホーム'],['register','レジ'],['map','サークルマップ'],['settings','設定']].map(([id,name])=>btn('tab',`<span class="${id==='home'?'home-icon':''}">${icon(id)}</span><span>${name}</span>`,tab===id?'selected':'',`data-tab="${id}" aria-current="${tab===id?'page':'false'}"`)).join('')}</nav></div>`;const nextNav=document.querySelector('.bottom');if(previousNav&&previousNav.dataset.language===navLanguage){for(const button of previousNav.querySelectorAll('[data-action=tab]')){const selected=button.dataset.tab===tab;button.classList.toggle('selected',selected);button.setAttribute('aria-current',selected?'page':'false')}nextNav.replaceWith(previousNav)}else if(nextNav)nextNav.dataset.language=navLanguage;if($('.products'))$('.products').scrollTop=scroll;for(const canvas of document.querySelectorAll('[data-product-image]')){const p=event().register.products.find(p=>p.id===canvas.dataset.productImage);drawThumbnail(canvas,p.image,p.thumbnail).catch(()=>{})}if(tab==='map')mountMap();tick();if(tab==='tasks'&&taskView==='timeline')requestAnimationFrame(()=>scrollWithin($('#now'),'center'))}
