function setup(){let body;if(setupStep===0&&installStep)body=`${intro(true)}<div class="install-card"><h2>まず、ホーム画面に置く</h2><p class="muted">次からはアイコンを押すだけで開けます。</p><ol class="install-steps">${installSteps().map(([title,note])=>`<li><strong>${title}</strong><span>${note}</span></li>`).join('')}</ol></div>${btn('install-done','次へ','primary')}`;else if(setupStep===0)body=`${intro(false)}<div class="setup-choices">${btn('setup-next',icon('plus')+'<span>イベントを新規作成</span>','setup-choice setup-create')}${btn('catalog',icon('download')+'<span>同梱データから選ぶ</span>','setup-choice setup-download')}</div>`;else if(setupStep===4)body=`<div class="setup-body"><h1>今回は、どんな参加スタイルですか？</h1><p class="muted">荷物とやることのひな形を用意します。あとから追加・削除できます。</p><div class="participation-options">${[['travel','遠征で参加','荷物の量：多い'],['local','近場から参加','荷物の量：少ない'],['empty','空の状態から作成','荷物の登録なし']].map(([key,title,note])=>btn('setup-style',`<strong>${title}</strong><span>（${note}）</span>`,'participation-choice',`data-style="${key}"`)).join('')}</div></div>${btn('setup-back','戻る','quiet')}`;else body=`<div class="setup-body"><div class="setup-steps" role="img" aria-label="${setupStep} / 4">${[1,2,3,4].map(i=>`<i class="${i<=setupStep?'on':''}"></i>`).join('')}</div><h1>${['','イベントの名前は？','いつ開催しますか？','入場は何時から？'][setupStep]}</h1>${field('', 'setup-value',setupStep===1?draft.name||'':setupStep===2?draft.date||'':draft.entry_time||'',setupStep===1?'text':setupStep===2?'date':'time',setupStep===1?'maxlength="40"':'')}${setupStep>1?btn('setup-unknown','まだ未定','quiet'):''}<p id="setup-error" class="error"></p></div>${btn('setup-next','次へ','primary')}${btn('setup-back','戻る','quiet')}`;$('#app').innerHTML=`<div class="setup"><div class="setup-inner" data-motion-screen="setup-${setupStep}-${installStep?1:0}">${body}</div></div>`;initTimeWheels(document.querySelector('#app'));if(setupStep===1)requestAnimationFrame(()=>document.querySelector('[name=setup-value]')?.focus({preventScroll:true}))}
