function bagEditor(isNew=false){const b=isNew?{}:event().bags[bagIndex],eid=state.active,id=b.id;modal(isNew?'バッグを作る':'バッグを編集',field('バッグの名前','name',b.name,'text','required')+check('宅配便で送ります','shipping',b.shipping)+'<p class="muted">チェックなし：いいえ、手荷物です</p>'+`<div class="shipping-fields" ${b.shipping?'':'hidden'}>`+field('送り先（会場・ホテル・友人宅など）','destination',b.destination)+field('送り状番号','tracking',b.tracking)+'</div>'+(!isNew?btn('bag-delete','バッグを削除','danger',`data-id="${b.id}"`):field('何を入れますか？','items','','text','maxlength="200"')),async f=>{const name=f.get('name').trim();if(!name||[...name].reduce((n,c)=>n+(c.charCodeAt(0)>255?2:1),0)>30)throw Error('名前は全角15字（半角30字）以内にしてください。');await changeEvent(e=>{if(isNew&&e.bags.length>=5)throw Error('バッグは5つまでです。');const item=e.bags.find(x=>x.id===id)||{id:C.uid(),items:[]};Object.assign(item,{name,shipping:f.has('shipping'),destination:f.has('shipping')?f.get('destination'):'',tracking:f.has('shipping')?f.get('tracking'):''});if(isNew){item.items=f.get('items').trim()?makeItems(f.get('items').trim().replace(/[\r\n]+/g,' ')):[];e.bags.push(item);bagIndex=e.bags.length-1}},true,eid)})}
