function productEditor(id){const p=event().register.products.find(x=>x.id===id)||{active:true},eid=state.active;imageDraft=p.image||'';modal('頒布物を登録・編集',field('頒布物名','name',p.name,'text','required maxlength="100"')+field('価格','price',p.price??0,'number','min="0" max="999999" required')+field('残り在庫','stock',p.stock??0,'number','min="0" max="999999" required')+field('頒布物画像','image','','file','accept="image/*"')+`<div class="crop-preview"><canvas id="crop-preview" width="480" height="480" tabindex="0" aria-label="${escapeText(tr('画像をドラッグして位置を調整'))}"></canvas></div><div class="crop-tools">${btn('crop-out','−','','aria-label="縮小"')}${btn('crop-in','＋','','aria-label="拡大"')}${ib('crop-reset','reset','リセット')}</div>`+`<div class="product-mark-field">頒布物の区分<div class="product-mark-options">${['','new','backlist','goods'].map(m=>`<label class="row"><input type="radio" name="mark" value="${m}" ${(p.release_mark||'')===m?'checked':''}><span>${({'new':'新刊','backlist':'既刊','goods':'グッズ'})[m]||'未分類'}</span></label>`).join('')}</div></div>`+check('頒布一覧に表示','active',p.active),async f=>{await changeEvent(e=>C.saveProduct(e.register,{name:f.get('name').trim(),price:Number(f.get('price')),stock:Number(f.get('stock')),image:imageDraft,active:f.has('active'),release_mark:f.get('mark'),thumbnail:cropEditor.getCrop()},id),true,eid)});cropEditor=createCropEditor(document.querySelector('#crop-preview'),imageDraft,p.thumbnail)}
async function imageFile(file){if(!file)return;if(file.size>20000000)throw Error('画像は20MB以下にしてください。');const bitmap=await createImageBitmap(file),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=bitmap.width*scale;canvas.height=bitmap.height*scale;canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);imageDraft=canvas.toDataURL('image/jpeg',.88).split(',')[1];bitmap.close();await cropEditor.setImage(imageDraft)}
function history(){const d=event().register,sales=d.sales.filter(s=>!s.cancelled);modal('売上・履歴',btn('analytics','売上分析','primary')+`<div class="stats"><div class="stat">売上<b>${yen(sales.reduce((n,s)=>n+s.total,0))}</b></div><div class="stat">会計<b>${sales.length}</b></div><div class="stat">頒布数<b>${sales.reduce((n,s)=>n+s.lines.reduce((n,l)=>n+l.quantity,0),0)}</b></div></div>`+d.sales.slice().reverse().map(s=>`<div class="card"><b>${s.kind==='gift'?tr('取り置き')+' · '+esc(s.recipient):yen(s.total)} ${s.cancelled?'（取消済み）':''}</b><p class="muted">${esc(new Date(s.at).toLocaleString(language(),{timeZone:'Asia/Tokyo'}))}</p>${s.lines.map(l=>`<div>${esc(l.name)} × ${l.quantity}</div>`).join('')}${s.cancelled?'':btn('sale-cancel','取消・在庫を戻す','danger',`data-id="${s.id}"`)}</div>`).join(''))}
async function sale(kind='cash',recipient=''){if(busy)return;busy=true;try{const id=C.uid();await changeEvent(e=>C.checkout(e.register,cart,paid,kind,recipient,id),false);cart={};paid=0;render();$('#modal').close();for(let i=0;i<65;i++){const p=document.createElement('i');p.className='confetti';p.style.cssText=`left:${Math.random()*100}vw;background:${['#dc7676','#e3c968','#85b48a','#93bac7'][i%4]};--x:${Math.random()*160-80}px;--r:${Math.random()*800-400}deg;animation-delay:${Math.random()*.2}s`;document.body.append(p);setTimeout(()=>p.remove(),1200)}toast('記録しました！')}finally{busy=false}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function backup(){download({format:'circle-prep-web-backup',version:2,exported_at:C.stamp(),data:state},`circle-prep-${clock().date}.json`)}
function restore(registerOnly=false){modal(registerOnly?'レジデータを読み込む':'バックアップを復元','<p class="alert">現在の記録を置き換えます。先に書き出して保管してください。</p>'+field('JSONファイル','import','','file','accept=".json,application/json" required')+check('置き換えに同意します','agree',false),async f=>{if(!f.has('agree'))throw Error('置き換えへの同意が必要です。');const file=f.get('import');if(file.size>40000000)throw Error('ファイルが大きすぎます。');const value=JSON.parse(await file.text());if(registerOnly){const d=C.parseTransfer(value);await changeEvent(e=>e.register=d);cart={};paid=0;render()}else{if(value.format!=='circle-prep-web-backup'||![1,2].includes(value.version))throw Error('Web版のバックアップではありません。');const next=C.migrateState(value.data);await mutate(s=>{for(const k of Object.keys(s))delete s[k];Object.assign(s,next)},false);setLanguage(state.preferences.language||'ja');cart={};paid=0;render()}toast('読み込みました')})}
function eventEditor(){const m=event().metadata,eid=state.active;modal('イベントを編集',field('イベント名','name',m.name,'text','required maxlength="40"')+field('開催日（未定なら空欄）','date',m.date,'date')+field('入場時刻（未定なら空欄）','entry_time',m.entry_time,'time'),async f=>changeEvent(e=>e.metadata=C.metadata({...e.metadata,...Object.fromEntries(f)}),true,eid))}
async function action(a,el,ev){const id=el.dataset.id;switch(a){
case 'migration-backup':{const data=await migrationSnapshot();if(data)download({format:'circle-prep-web-backup',version:1,exported_at:C.stamp(),data},'circle-prep-before-stable-ids.json');break}
case 'close':$('#modal').close();break;
case 'tab':tab=el.dataset.tab;render();break;
case 'setup-style':{const style=el.dataset.style;await mutate(s=>C.addEvent(s,{...draft,participation_style:style}));setupStep=0;draft={};tab='home';bagIndex=0;render();break}case 'setup-next':await setupNext();break;case 'setup-unknown':await setupNext(true);break;case 'setup-back':if(setupStep<=1&&state.events.length){setupStep=0;draft={};render();break}setupStep=Math.max(0,setupStep-1);setup();break;
case 'install-done':{installStep=false;try{localStorage.setItem(installKey,'1')}catch(e){}const wipe=document.createElement('div');wipe.className='wipe';document.body.append(wipe);setTimeout(setup,100);setTimeout(()=>wipe.remove(),180);break}
case 'catalog':await catalog();break;case 'catalog-fetch':await fetchCatalog();break;case 'catalog-local':await fetchCatalog(true);break;case 'catalog-select':{if(Object.values(cart).some(n=>n>0))throw Error('先に会計を完了してください。');const m=catalogEvents[Number(el.dataset.index)];if(!m)throw Error('イベントを選び直してください。');if(state.events.some(e=>e.metadata.key===m.key))throw Error('このイベントは登録済みです。');draft={...m};$('#modal').close();setupStep=4;setup();break}
case 'event-delete':confirmEventDelete(id);break;case 'event-delete-confirm':{if(id===state.active&&Object.values(cart).some(n=>n>0))throw Error('先に会計を完了してください。');const wasActive=id===state.active;draft={};setupStep=0;await mutate(s=>C.removeEvent(s,id));if(wasActive){cart={};paid=0;bagIndex=0}$('#modal').close();render();break}case 'crop-in':cropEditor.zoom(1.15);break;case 'crop-out':cropEditor.zoom(1/1.15);break;case 'crop-reset':cropEditor.reset();break;case 'event-edit':eventEditor();break;case 'event-add':if(Object.values(cart).some(n=>n>0))throw Error('先に会計を完了してください。');draft={};setupStep=1;setup();break;
case 'event-switch':if(Object.values(cart).some(n=>n>0))throw Error('先に会計を完了してください。');await mutate(s=>s.active=id);bagIndex=0;paid=0;render();break;
case 'language':await mutate(s=>s.preferences.language=el.dataset.language,false);setLanguage(el.dataset.language);render();break;
case 'font':await mutate(s=>s.preferences.size=Number(el.dataset.size));break;
case 'bag-select':bagIndex=Number(el.dataset.index);render();break;case 'bag-open':bagIndex=Number(el.dataset.index);tab='bags';render();break;
case 'bag-add':bagEditor(true);break;case 'bag-edit':bagEditor();break;
case 'bag-delete':{const b=event().bags.find(x=>x.id===id);if(b.items.length&&!confirm(tr('中の持ち物もまとめて削除しますか？')))break;await changeEvent(e=>e.bags=e.bags.filter(x=>x.id!==id));bagIndex=Math.min(bagIndex,4);$('#modal').close();break}
case 'items-add':itemsEditor();break;case 'item-edit':itemsEditor(id);break;case 'item-delete':await changeEvent(e=>{const b=e.bags[bagIndex];b.items=b.items.filter(i=>i.id!==id)});$('#modal').close();break;
case 'item-check':await changeEvent(e=>{const i=e.bags.find(b=>b.id===el.dataset.bag).items.find(i=>i.id===id);i.done=el.checked},false);el.closest('.listrow')?.querySelector('.text')?.classList.toggle('done',el.checked);break;
case 'task-add':taskEditor();break;case 'task-edit':taskEditor(id);break;case 'task-check':await changeEvent(e=>e.tasks.find(t=>t.id===id).done=el.checked);break;case 'task-delete':await changeEvent(e=>e.tasks=e.tasks.filter(t=>t.id!==id));toast('削除しました');break;case 'task-view':taskView=el.dataset.view;render();break;
case 'products':productList();break;case 'product-delete':confirmProductDelete(id);break;
case 'product-delete-confirm':{const eid=state.active;await changeEvent(e=>C.removeProduct(e.register,id),true,eid);delete cart[id];productList();break}
case 'product-add':productEditor();break;case 'product-edit':productEditor(id);break;
case 'product-tap':{const p=event().register.products.find(x=>x.id===id);if((cart[id]||0)>=p.stock)break;cart[id]=(cart[id]||0)+1;burst(el,ev);render();break}case 'product-reset':delete cart[id];render();break;
case 'key':paid=C.keypad(paid,el.dataset.key,total());refreshCheckout();break;
case 'reg-mode':await mutate(s=>s.preferences.regMode=regModes.some(([m])=>m===el.dataset.mode)?el.dataset.mode:'fast',false);paid=0;refreshCheckout();break;
case 'reg-detail':registerDetail();break;
case 'checkout':if(regMode()==='fast')paid=total();await sale();break;case 'gift':modal('取り置き（0円）',field('誰に渡しましたか？','recipient','','text','required maxlength="100"'),async f=>{busy=false;await sale('gift',f.get('recipient'))});break;
case 'analytics':openRegisterAnalytics(event().register,modal);break;case 'history':history();break;case 'sale-cancel':if(confirm(tr('この会計を取り消して在庫を戻しますか？'))){await changeEvent(e=>C.cancelSale(e.register,id));history()}break;
case 'reg-data':modal('レジのデータ',`<p>PC版とレジの記録をファイルで受け渡せます。</p>${btn('reg-export','書き出す')}${btn('reg-import','読み込む')}`);break;
case 'grid':await changeEvent(e=>e.grid=el.dataset.grid);if($('#modal').open)registerDetail();break;case 'reg-export':download(C.registerTransfer(event().register),'kemoket-register.json');break;case 'reg-import':restore(true);break;case 'backup':backup();break;
case 'open-release-page':if(window.CirclePrepAndroid){ev.preventDefault();if(typeof window.CirclePrepAndroid.openReleases==='function')window.CirclePrepAndroid.openReleases();else toast('ブラウザーでGitHubの配布ページを開いてください。')}break;
case 'auto-update':if(typeof window.CirclePrepAndroid?.checkAndUpdate==='function')window.CirclePrepAndroid.checkAndUpdate();else confirmApkUpdate();break;
case 'apk-update':confirmApkUpdate();break;
case 'apk-update-go':$('#modal').close();window.CirclePrepAndroid?.update();break;case 'restore':restore();break;
}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled)return;ev.stopPropagation();try{await action(el.dataset.action,el,ev)}catch(e){toast(e.message);if($('#setup-error'))$('#setup-error').textContent=e.message}});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.isComposing&&ev.keyCode!==229&&ev.target.matches?.('.setup input[name=setup-value]')){ev.preventDefault();document.querySelector('.setup [data-action=setup-next]')?.click();return}if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[role=button]')){ev.preventDefault();ev.target.click()}});
document.addEventListener('input',ev=>{if(ev.target.id==='guide-query'){const q=ev.target.value.trim().toLowerCase();document.querySelectorAll('.guide-card').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',async ev=>{if(ev.target.name==='image')try{await imageFile(ev.target.files[0])}catch(e){toast(e.message)}});
installBagDrag({getEvent:event,changeEvent,render,toast,tr,trash:icon('trash')});
installMap({getEvent:event,changeEvent,render,modal,field,toast});
installNotes({getEvent:event,changeEvent,render,modal,field,toast});
try{state=await readState();migrationBackupAvailable=await migrationSnapshot(true);await initializeLanguage(state.preferences.language||'ja');if(!state.events.some(e=>e.id===state.active)&&state.events.length)state.active=state.events[0].id;const params=new URLSearchParams(location.search);const isDemo=params.has('demo')||/\/preview\/(?:index\.html)?$/.test(location.pathname);demoMode=isDemo;if(!isDemo){const log=state.log||[];if(log[log.length-1]?.version!==appVersion){await changeState(s=>{const rows=s.log||[];rows.push({at:C.stamp(),version:appVersion});s.log=rows.slice(-50)});state=await readState()}}tab=isDemo&&['home','bags','tasks','register'].includes(params.get('view'))?params.get('view'):state.preferences.start||'home';installStep=!isDemo&&!androidApp()&&!homeScreen()&&!installSeen()&&!state.events.length;render();if(isDemo){document.body.classList.add('demo-mode');import('./demo-play.mjs').then(m=>m.playDemo(tab)).catch(()=>{})}setInterval(tick,1000);if(!isDemo&&'BroadcastChannel'in window){channel=new BroadcastChannel(new URLSearchParams(location.search).has('test')?'circle-prep-test':'circle-prep');channel.onmessage=async()=>{state=await readState();setLanguage(state.preferences.language||'ja');if(!$('#modal').open)render()}}if(!isDemo&&'serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offline=true;if($('#offline-status'))$('#offline-status').textContent='オフライン起動の準備ができました。'}).catch(()=>toast('オフライン機能を準備できませんでした。HTTPSで開いてください。'))}}catch(e){$('#app').innerHTML=`<div class="card"><h1>保存領域を開けませんでした</h1><p>${esc(e.message)}</p><p>通常モードのブラウザで開き直してください。</p></div>`}

document.addEventListener('change',e=>{if(e.target.name==='shipping'){const fields=e.target.closest('form')?.querySelector('.shipping-fields');if(fields)fields.hidden=!e.target.checked}});

window.addEventListener('android-update',e=>toast(
 e.detail==='settings'?'「不明なアプリのインストール」を許可してから、もう一度お試しください。':
 e.detail==='denied'?'許可されなかったため更新できません。':
 e.detail==='browser'?'GitHubの配布ページを開けませんでした。':e.detail==='cancelled'?'更新をやめました。':'APKを開けませんでした。'));

window.addEventListener('android-auto-update',e=>{
 const detail=e.detail||{},status=detail.status;
 const messages={checking:'最新版を確認しています…',downloading:'APKをダウンロードしています… {percent}%',verifying:'APKを確認しています…',current:'この端末は公開版と同じか新しいバージョンです。',ready:'更新の準備ができました。',permission:'Androidの設定で、このアプリからのインストールを許可してください。',installer:'Androidの画面で更新を確認してください。',invalid:'更新ファイルの確認に失敗しました。インストールを中止しました。',failed:'更新できませんでした。通信を確認して、もう一度お試しください。',denied:'インストールが許可されなかったため、更新を中止しました。'};
 const text=tr(messages[status]||'更新できませんでした。通信を確認して、もう一度お試しください。').replace('{percent}',String(Math.max(0,Math.min(100,Number(detail.percent)||0))));
 const box=document.querySelector('#auto-update-status');if(box)box.textContent=text;
 const button=document.querySelector('#auto-update-button');if(button)button.disabled=['checking','downloading','verifying'].includes(status);
 if(['current','invalid','failed','denied','installer'].includes(status))toast(text);
});

window.addEventListener('android-export',e=>toast(e.detail?'保存しました':'保存できませんでした'));
